import calendar
from datetime import date


def add_months(day, months):
    """The date `months` months after `day`, clamped to the end of the month. See TASK.md."""
    if not isinstance(months, int) or isinstance(months, bool):
        raise TypeError("months must be an int (but not bool)")

    month_index = day.year * 12 + (day.month - 1) + months
    year, month_index = divmod(month_index, 12)
    month = month_index + 1
    if not 1 <= year <= 9999:
        raise ValueError("resulting date is outside the supported year range")

    last_day = calendar.monthrange(year, month)[1]
    return date(year, month, min(day.day, last_day))


def months_between(start, end):
    """Whole months from `start` to `end`. See TASK.md."""
    if start > end:
        return -months_between(end, start)

    month_difference = (end.year - start.year) * 12 + end.month - start.month
    if add_months(start, month_difference) > end:
        month_difference -= 1
    return month_difference
